import { test, expect } from '@playwright/test';

test.describe('Loading Skeleton - API Data Fetching', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should display loading skeleton while API data is fetching', async ({ page }) => {
    // Intercept the API call
    await page.route('**/api/dashboard/data', (route) => {
      route.abort('blockedbyclient');
    });

    // Verify loading skeleton is visible
    const loadingSkeleton = page.getByTestId('loading-skeleton');
    await expect(loadingSkeleton).toBeVisible();

    // Verify data content is not yet visible
    const dataContent = page.getByTestId('dashboard-data');
    await expect(dataContent).not.toBeVisible();

    // Verify loading indicator is visible
    const loadingIndicator = page.getByTestId('loading-indicator');
    await expect(loadingIndicator).toBeVisible();

    // Wait for API response
    await page.waitForTimeout(1000);

    // Verify loading skeleton is removed
    await expect(loadingSkeleton).not.toBeVisible();

    // Verify data content is now visible
    await expect(dataContent).toBeVisible();

    // Verify data is displayed
    const welcomeMessage = page.getByText('Welcome Back');
    await expect(welcomeMessage).toBeVisible();
  });

  test('should handle API error and display error message instead of skeleton', async ({ page }) => {
    // Intercept the API call and return an error
    await page.route('**/api/dashboard/data', (route) => {
      route.abort('failed');
    });

    // Verify loading skeleton is displayed initially
    const loadingSkeleton = page.getByTestId('loading-skeleton');
    await expect(loadingSkeleton).toBeVisible();

    // Wait for API error
    await page.waitForTimeout(1000);

    // Verify loading skeleton is removed
    await expect(loadingSkeleton).not.toBeVisible();

    // Verify error message is displayed
    const errorMessage = page.getByTestId('error-message');
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText('Failed to load data');

    // Verify data content is not visible
    const dataContent = page.getByTestId('dashboard-data');
    await expect(dataContent).not.toBeVisible();

    // Verify retry button is available
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();
  });
});
